      $fwrite(file_mantra, "sequence_detected,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", sequence_detected);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting Deterministic Mutation Testing Stimuli...");

    // Initialize Signals
    data_in = 0;
    rst_n = 0;
    #20;
    rst_n = 1;
    #20;

    // ---------------------------------------------------------
    // Test Case 1: Basic Sequence Detection (1-0-0-1)
    // Targets: State transitions IDLE->S1->S2->S3->S4
    // ---------------------------------------------------------
    @(negedge clk); data_in = 1; // IDLE -> S1
    @(negedge clk); data_in = 0; // S1 -> S2
    @(negedge clk); data_in = 0; // S2 -> S3
    @(negedge clk); data_in = 1; // S3 -> S4 (Sequence Detected)

    // ---------------------------------------------------------
    // Test Case 2: Overlap Handling (1-0-0-1-0-0-1)
    // Targets: S4 -> S2 transition (Overlap logic)
    // ---------------------------------------------------------
    @(negedge clk); data_in = 0; // S4 -> S2 (Overlap start)
    @(negedge clk); data_in = 0; // S2 -> S3
    @(negedge clk); data_in = 1; // S3 -> S4 (Detected again)

    // ---------------------------------------------------------
    // Test Case 3: S4 Exit to S1 (Non-overlap start)
    // Targets: S4 -> S1 transition
    // ---------------------------------------------------------
    @(negedge clk); data_in = 1; // S4 -> S1
    @(negedge clk); data_in = 1; // S1 -> S1 (Hold)
    @(negedge clk); data_in = 0; // S1 -> S2 (Verify we were in S1)

    // ---------------------------------------------------------
    // Test Case 4: Asynchronous Reset Verification
    // Targets: Sensitivity list mutations (removing negedge rst_n)
    // ---------------------------------------------------------
    // First, reach S4 to assert output high
    @(negedge clk); data_in = 0; // S3
    @(negedge clk); data_in = 1; // S4 (Next Posedge)

    @(posedge clk); // Wait for state update (Output = 1)
    #2;             // Wait small delay into cycle
    rst_n = 0;      // Assert Reset Asynchronously
    #3;             // Hold Reset (Output should drop to 0 immediately)
    rst_n = 1;      // Release Reset

    // ---------------------------------------------------------
    // Test Case 5: False Path / Branch Coverage
    // Targets: Else branches in state logic
    // ---------------------------------------------------------
    // Path: 1-0-1 (S1->S2->S1)
    @(negedge clk); data_in = 1; // S1
    @(negedge clk); data_in = 0; // S2
    @(negedge clk); data_in = 1; // S1 (Fail sequence)

    // Path: 1-0-0-0 (S1->S2->S3->IDLE)
    @(negedge clk); data_in = 0; // S2
    @(negedge clk); data_in = 0; // S3
    @(negedge clk); data_in = 0; // IDLE (Fail sequence)

    // ---------------------------------------------------------
    // Test Case 6: Stuck-at / Stress Patterns
    // Targets: Operator mutations, stuck states
    // ---------------------------------------------------------
    // Stuck-at-1 (Should hold S1)
    repeat(5) begin
        @(negedge clk); data_in = 1;
    end

    // Stuck-at-0 (Should cycle to IDLE)
    repeat(5) begin
        @(negedge clk); data_in = 0;
    end

    // Alternating Pattern (High switching activity)
    repeat(5) begin
        @(negedge clk); data_in = 1;
        @(negedge clk); data_in = 0;
    end

    // 4. Handover to Original Testbench
    $display("LLM: Tests Finished. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


